package org.sleepwell.app;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.*;
import android.view.View;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.runner.lifecycle.*;
import androidx.test.uiautomator.*;
import org.junit.Test;
import java.io.File;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import static org.junit.Assert.*;

/** Disposable CI configuration only: every Preview output is an injected fake. */
public class SnoreCueSettingsNativeTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);
    private SnoringCuesActivity focused() {final SnoringCuesActivity[] found={null};i.runOnMainSync(()->{for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(a instanceof SnoringCuesActivity&&a.hasWindowFocus()&&a.getWindow().getDecorView().isAttachedToWindow())found[0]=(SnoringCuesActivity)a;});return found[0];}
    private SnoringCuesActivity awaitFocused(SnoringCuesActivity previous){long end=SystemClock.elapsedRealtime()+5000;SnoringCuesActivity a;while((a=focused())==null||a==previous){assertTrue("A distinct resumed and focused cue screen is required",SystemClock.elapsedRealtime()<end);SystemClock.sleep(50);}return a;}
    private void destroyed(Activity a){long end=SystemClock.elapsedRealtime()+5000;boolean[] gone={false};while(!gone[0]){i.runOnMainSync(()->gone[0]=a.isDestroyed());assertTrue("The previous cue screen must be destroyed",gone[0]||SystemClock.elapsedRealtime()<end);if(!gone[0])SystemClock.sleep(50);}}
    private void choose(String section,String value){UiObject2 group=device.wait(Until.findObject(By.desc(section+" options")),3000);assertNotNull(group);UiObject2 choice=group.findObject(By.desc(value));assertNotNull(choice);choice.click();assertTrue(device.wait(Until.hasObject(By.desc(section+" options").hasDescendant(By.desc(value).selected(true))),3000));device.waitForIdle();}
    private SnoringCuesActivity open(){c.startActivity(new Intent(c,SnoringCuesActivity.class).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));assertTrue(device.wait(Until.hasObject(By.text("Snoring cues")),5000));return awaitFocused(null);}
    private void visibleAction(String title){UiObject2 v=device.findObject(By.desc(title));if(v==null)v=device.findObject(By.text(title));assertNotNull(title,v);android.graphics.Rect bounds=v.getVisibleBounds();int minimum=Design.dp(c,48);assertTrue(title+" needs a full 48dp touch target",bounds.height()>=minimum&&bounds.width()>=minimum);assertTrue(title+" must remain above navigation",bounds.bottom<device.getDisplayHeight()-Design.dp(c,20));}
    private void capture(String name)throws Exception{SnoringCuesActivity a=awaitFocused(null);visibleAction("Save settings");visibleAction("Preview cue");CountDownLatch frame=new CountDownLatch(1);i.runOnMainSync(()->{View decor=a.getWindow().getDecorView();assertTrue(a.hasWindowFocus());assertTrue(decor.isAttachedToWindow());assertTrue(decor.getWidth()>0&&decor.getHeight()>0);assertTrue(decor.isHardwareAccelerated());decor.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);decor.invalidate();});assertTrue("Commit the focused destination frame",frame.await(5,TimeUnit.SECONDS));File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());device.waitForIdle();assertTrue(device.takeScreenshot(new File(folder,name+".png")));}
    @SuppressWarnings("unchecked") private void restore(Map<String,?> values){SharedPreferences.Editor e=Prefs.of(c).edit().clear();for(Map.Entry<String,?> item:values.entrySet()){String k=item.getKey();Object v=item.getValue();if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Float)e.putFloat(k,(Float)v);else if(v instanceof Set)e.putStringSet(k,(Set<String>)v);else e.putString(k,(String)v);}assertTrue(e.commit());}
    @Test public void savedSettingsSurviveRecreationAndControlFakeCueBehavior() throws Exception {
        org.junit.Assume.assumeTrue(android.os.Build.HARDWARE.contains("ranchu")||android.os.Build.HARDWARE.contains("goldfish"));org.junit.Assume.assumeTrue(InstrumentationRegistry.getArguments().getString("ciReview","").equals("true"));
        assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));Map<String,?> before=new HashMap<>(Prefs.of(c).getAll());boolean granted=c.checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED;
        SnoringCuesActivity.PreviewFactory priorFactory=SnoringCuesActivity.previewFactory;LongSupplier priorClock=SnoringCuesActivity.previewClock;SnoreCuePolicy.Budget priorBudget=SnoringCuesActivity.previewBudget;
        List<Activity> owned=new CopyOnWriteArrayList<>();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){if(a instanceof SnoringCuesActivity)owned.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
        Application application=(Application)c.getApplicationContext();application.registerActivityLifecycleCallbacks(lifecycle);int[] allocations={0},previewPlays={0},closes={0};List<BooleanSupplier> tokens=new ArrayList<>();
        try{
            SnoringCuesActivity.previewBudget=new SnoreCuePolicy.Budget();SnoringCuesActivity.previewClock=()->1000L;SnoringCuesActivity.previewFactory=(context,allowed)->{allocations[0]++;tokens.add(allowed);return new SnoreCuePolicy.Device(){public void play(SnoreCuePolicy.Settings value){assertTrue(allowed.getAsBoolean());assertFalse(Prefs.flag(c,"ringing"));assertEquals(1,value.intensity);assertEquals(1,value.repeats);assertEquals(SnoreCuePolicy.Mode.VIBRATION,value.mode);previewPlays[0]++;}public void close(){closes[0]++;}};};
            if(!granted)i.getUiAutomation().grantRuntimePermission(c.getPackageName(),Manifest.permission.RECORD_AUDIO);
            assertTrue(Prefs.of(c).edit().putBoolean("snoreCues",false).putBoolean("noiseEnabled",true).putInt("snoreCueMode",1).putInt("snoreCueIntensity",1).putInt("snoreCueRepeats",1).putInt("snoreCueSensitivity",1).commit());SnoringCuesActivity first=open();capture("snore-settings-default");assertEquals(0,allocations[0]);Map<String,?> draftBaseline=new HashMap<>(Prefs.of(c).getAll());
            device.findObject(By.desc("Preview cue")).click();assertTrue(device.wait(Until.hasObject(By.text("Preview requested at low intensity.")),3000));assertEquals(1,allocations[0]);assertEquals(1,previewPlays[0]);assertEquals(draftBaseline,Prefs.of(c).getAll());assertFalse(Prefs.flag(c,"snoreCues"));capture("snore-settings-preview");
            i.runOnMainSync(first::recreate);SnoringCuesActivity replacement=awaitFocused(first);destroyed(first);assertEquals(1,closes[0]);assertFalse("The old output token is revoked",tokens.get(0).getAsBoolean());device.findObject(By.desc("Preview cue")).click();assertTrue(device.wait(Until.hasObject(By.text("Wait two minutes before previewing again.")),3000));assertEquals(1,previewPlays[0]);assertEquals(1,allocations[0]);
            device.findObject(By.desc("Respond to snoring estimates")).click();choose("Alert type","Both");choose("Intensity","Medium");choose("Repeats","3");choose("Detection sensitivity","High");capture("snore-settings-selected");
            i.runOnMainSync(replacement::recreate);SnoringCuesActivity selected=awaitFocused(replacement);destroyed(replacement);assertTrue(device.wait(Until.hasObject(By.desc("Respond to snoring estimates").checked(true)),5000));assertTrue(device.findObject(By.desc("Alert type options")).findObject(By.desc("Both")).isSelected());capture("snore-settings-recreated");
            device.findObject(By.text("Save settings")).click();destroyed(selected);SnoreCuePolicy.Settings settings=SnoreCueOutput.settings(c);assertTrue(settings.enabled);assertEquals(SnoreCuePolicy.Mode.BOTH,settings.mode);assertEquals(2,settings.intensity);assertEquals(3,settings.repeats);assertEquals(2,settings.sensitivity);
            int[] plays={0};SnoreCuePolicy policy=new SnoreCuePolicy(new SnoreCuePolicy.Budget(),()->new SnoreCuePolicy.Device(){public void play(SnoreCuePolicy.Settings value){assertEquals(3,value.repeats);plays[0]++;}public void close(){}},()->fail());assertTrue(policy.event("snoring",.7,0,settings));assertFalse(policy.event("snoring",.9,1000,settings));assertFalse(policy.event("speech",.9,120000,settings));policy.close();assertEquals(1,plays[0]);SnoringCuesActivity reopened=open();assertTrue(device.hasObject(By.desc("Respond to snoring estimates").checked(true)));capture("snore-settings-reopened");device.findObject(By.desc("Preview cue")).click();assertTrue(device.wait(Until.hasObject(By.text("Wait two minutes before previewing again.")),3000));assertEquals(1,previewPlays[0]);choose("Repeats","1");device.pressBack();destroyed(reopened);assertEquals(3,SnoreCueOutput.settings(c).repeats);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));
        }finally{try{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});for(Activity a:owned)destroyed(a);}finally{application.unregisterActivityLifecycleCallbacks(lifecycle);SnoringCuesActivity.previewFactory=priorFactory;SnoringCuesActivity.previewClock=priorClock;SnoringCuesActivity.previewBudget=priorBudget;restore(before);/* Revocation kills instrumentation; this grant belongs only to the disposable emulator. */assertEquals(before,Prefs.of(c).getAll());}}
    }
}
